    # Find a solid, nonzero divider row or column.
    divider = None
    for r in range(h):
        if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r]):
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                divider = ("col", c)
                break

    if divider is None:
        return grid

    axis, i = divider
    if axis == "row":
        parts = [grid[:i], grid[i + 1:]]
    else:
        parts = [
            [row[:i] for row in grid],
            [row[i + 1:] for row in grid],
        ]

    chosen = min(parts, key=lambda part: sum(x != 0 for row in part for x in row))
    return [[2 if x != 0 else 0 for x in row] for row in chosen]
