def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split at the solid nonzero separator.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            first = grid[:r]
            second = grid[r + 1:]
            return [
                [2 if a != 0 and b != 0 else 0 for a, b in zip(row_a, row_b)]
                for row_a, row_b in zip(first, second)
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            return [
                [2 if grid[r][a] != 0 and grid[r][c + 1 + a] != 0 else 0
                 for a in range(min(c, w - c - 1))]
                for r in range(h)
            ]

    return grid
